$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing.Common,System.Drawing.Primitives,System.Runtime,System.Collections,System.Runtime.InteropServices,System.Private.Windows.GdiPlus,System.Private.Windows.Core,System.Console -TypeDefinition @"
using System;using System.Drawing;using System.Drawing.Imaging;using System.Collections.Generic;
public class StaminaRingImport{
 public class Part{public List<int> Pixels=new List<int>();public Rectangle Bounds;}
 public static byte[] Read(Bitmap b){var d=b.LockBits(new Rectangle(0,0,b.Width,b.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);var a=new byte[d.Stride*b.Height];System.Runtime.InteropServices.Marshal.Copy(d.Scan0,a,0,a.Length);b.UnlockBits(d);return a;}
 public static List<Part> Split(byte[] a,int w,int h){var seen=new bool[w*h];var list=new List<Part>();for(int i=0;i<w*h;i++){if(seen[i]||!Bright(a,i))continue;var p=new Part();var q=new Queue<int>();q.Enqueue(i);seen[i]=true;int l=w,r=0,t=h,b=0;while(q.Count>0){int k=q.Dequeue(),x=k%w,y=k/w;p.Pixels.Add(k);l=Math.Min(l,x);r=Math.Max(r,x);t=Math.Min(t,y);b=Math.Max(b,y);foreach(int j in new int[]{k-1,k+1,k-w,k+w}){if(j<0||j>=w*h||seen[j]||Math.Abs(j%w-x)>1||!Bright(a,j))continue;seen[j]=true;q.Enqueue(j);}}if(p.Pixels.Count>3000){p.Bounds=Rectangle.FromLTRB(l,t,r+1,b+1);list.Add(p);}}list.Sort((x,y)=>y.Pixels.Count.CompareTo(x.Pixels.Count));return list;}
 static bool Bright(byte[] a,int k){return a[k*4+3]>180&&a[k*4+2]>185&&a[k*4+1]>135;}

 public static void Save(byte[] a,int w,int h,string file){using(var b=new Bitmap(w,h,PixelFormat.Format32bppArgb)){var d=b.LockBits(new Rectangle(0,0,w,h),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);System.Runtime.InteropServices.Marshal.Copy(a,0,d.Scan0,a.Length);b.UnlockBits(d);b.Save(file);}}
 public static byte[] Crop(byte[] a,int w,Rectangle r){var o=new byte[r.Width*r.Height*4];for(int y=0;y<r.Height;y++)Array.Copy(a,((y+r.Y)*w+r.X)*4,o,y*r.Width*4,r.Width*4);return o;}
 public static void Build(string root){using(var b=new Bitmap(System.IO.Path.Combine(root,"original.png"))){int w=b.Width,h=b.Height;var original=Read(b);var parts=Split(original,w,h);if(parts.Count!=3)throw new Exception("Expected 2 ring sections and 1 lightning interior");var mask=new byte[original.Length];var baseLayer=(byte[])original.Clone();var boltLayer=new byte[original.Length];var boltCore=new bool[w*h];foreach(int k in parts[2].Pixels)boltCore[k]=true;
 double rr=0,gg=0,bb=0;int n=0;foreach(var p in parts.GetRange(0,2))foreach(int k in p.Pixels)if(original[k*4]>150){rr+=original[k*4+2];gg+=original[k*4+1];bb+=original[k*4];n++;}if(n<1000)throw new Exception("Cream reference missing");rr/=n;gg/=n;bb/=n;
 foreach(var p in parts.GetRange(0,2))foreach(int k in p.Pixels){int at=k*4;mask[at+2]=255;mask[at+3]=255;baseLayer[at]=(byte)Math.Round(bb);baseLayer[at+1]=(byte)Math.Round(gg);baseLayer[at+2]=(byte)Math.Round(rr);}
 // Separate only the authored lightning, including its brown contour. The base keeps the original pose underneath.
 var distance=new int[w*h];Array.Fill(distance,10000);var queue=new Queue<int>();foreach(int k in parts[2].Pixels){distance[k]=0;queue.Enqueue(k);}while(queue.Count>0){int k=queue.Dequeue(),x=k%w;if(distance[k]>=32)continue;foreach(int j in new int[]{k-1,k+1,k-w,k+w}){if(j<0||j>=w*h||Math.Abs(j%w-x)>1||distance[j]<=distance[k]+1)continue;distance[j]=distance[k]+1;queue.Enqueue(j);}}
 for(int k=0;k<w*h;k++){int at=k*4;if(boltCore[k]){mask[at+1]=255;mask[at+3]=255;}bool brown=original[at+2]<190&&original[at+1]<150; if(boltCore[k]||(distance[k]<=32&&brown&&original[at+3]>0))Array.Copy(original,at,boltLayer,at,4);}

 for(int k=0;k<w*h;k++){int at=k*4;if(original[at+3]>10&&original[at+2]<185&&original[at+1]<150){mask[at]=255;mask[at+3]=255;}}
 // Close only tiny enclosed pigment holes inside the ring; leave the authored contour intact.
 var visited=new bool[w*h];var outside=new Queue<int>();for(int k=0;k<w*h;k++)if(k%w==0||k%w==w-1||k/w==0||k/w==h-1){if(mask[k*4+2]==0&&!visited[k]){visited[k]=true;outside.Enqueue(k);}}while(outside.Count>0){int k=outside.Dequeue(),x=k%w;foreach(int j in new int[]{k-1,k+1,k-w,k+w}){if(j<0||j>=w*h||Math.Abs(j%w-x)>1||visited[j]||mask[j*4+2]!=0)continue;visited[j]=true;outside.Enqueue(j);}}for(int i=0;i<w*h;i++){if(visited[i]||mask[i*4+2]!=0)continue;var hole=new List<int>();outside.Enqueue(i);visited[i]=true;while(outside.Count>0){int k=outside.Dequeue(),x=k%w;hole.Add(k);foreach(int j in new int[]{k-1,k+1,k-w,k+w}){if(j<0||j>=w*h||Math.Abs(j%w-x)>1||visited[j]||mask[j*4+2]!=0)continue;visited[j]=true;outside.Enqueue(j);}}if(hole.Count<=256)foreach(int k in hole){int at=k*4;if(mask[at+1]>0||original[at+3]<200)continue;mask[at+2]=255;mask[at+3]=255;}}
 for(int k=0;k<w*h;k++)if(mask[k*4+2]>0){int at=k*4;baseLayer[at]=(byte)Math.Round(bb);baseLayer[at+1]=(byte)Math.Round(gg);baseLayer[at+2]=(byte)Math.Round(rr);boltLayer[at+3]=0;}
 int l=w,r=0,t=h,bt=0;for(int k=0;k<w*h;k++)if(original[k*4+3]>160){l=Math.Min(l,k%w);r=Math.Max(r,k%w);t=Math.Min(t,k/w);bt=Math.Max(bt,k/w);}var crop=Rectangle.FromLTRB(Math.Max(0,l-4),Math.Max(0,t-4),Math.Min(w,r+5),Math.Min(h,bt+5));string dir=System.IO.Path.Combine(root,"derived");System.IO.Directory.CreateDirectory(dir);
 Save(Crop(original,w,crop),crop.Width,crop.Height,System.IO.Path.Combine(dir,"source.png"));Save(Crop(baseLayer,w,crop),crop.Width,crop.Height,System.IO.Path.Combine(dir,"base.png"));Save(Crop(mask,w,crop),crop.Width,crop.Height,System.IO.Path.Combine(dir,"masks.png"));Save(Crop(boltLayer,w,crop),crop.Width,crop.Height,System.IO.Path.Combine(dir,"lightning.png"));
 var culture=System.Globalization.CultureInfo.InvariantCulture;double centerX=626,centerY=617;string gd="extends RefCounted\nconst SOURCE_SIZE := Vector2("+crop.Width+","+crop.Height+")\nconst CENTER := Vector2("+((centerX-crop.X)/crop.Width).ToString("F8",culture)+","+((centerY-crop.Y)/crop.Height).ToString("F8",culture)+")\nconst BOLT_PIVOT := Vector2("+((666.0-crop.X)/crop.Width).ToString("F8",culture)+","+((591.0-crop.Y)/crop.Height).ToString("F8",culture)+")\nconst START_RADIANS := -PI/4.0\n";System.IO.File.WriteAllText(System.IO.Path.Combine(root,"regions.gd"),gd);Console.WriteLine("CROP "+crop+" ring_pixels="+(parts[0].Pixels.Count+parts[1].Pixels.Count)+" bolt_pixels="+parts[2].Pixels.Count+" cream="+rr+","+gg+","+bb);}}
 public static void Analyze(string file){using(var b=new Bitmap(file)){Console.WriteLine("SOURCE "+b.Width+"x"+b.Height);var a=Read(b);var list=Split(a,b.Width,b.Height);for(int i=0;i<list.Count;i++)Console.WriteLine("PART "+i+" area="+list[i].Pixels.Count+" rect="+list[i].Bounds);}}
}
"@
[StaminaRingImport]::Analyze((Join-Path $PSScriptRoot '../godot/assets/UI/HUD/stamina_ring/original.png'))


[StaminaRingImport]::Build((Join-Path $PSScriptRoot '../godot/assets/UI/HUD/stamina_ring'))
